INSERT INTO `Package` (`slug`, `name`, `category`, `country`, `region`, `city`, `tagline`, `nights`, `days`, `occupancy`, `price`, `currency`, `hotelStars`, `rating`, `featured`, `published`, `order`, `image`, `gallery`, `tags`, `includes`, `highlights`, `itinerary`, `createdAt`, `updatedAt`) VALUES
  ('escape-to-armenia', 'Escape to Armenia', 'tour', 'Armenia', 'Caucasus', 'Yerevan', 'Ancient monasteries, alpine lakes & warm hospitality', 3, 4, 'Quad sharing', 1250, 'AED', 4, 4.9, 1, 1, 0, 'https://images.unsplash.com/photo-1585687501004-615dfdfb6f37?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1585687501004-615dfdfb6f37?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600241318523-1a2a56b8a41f?auto=format&fit=crop&w=1200&q=80"]', '["Culture","Nature","Best Seller"]', '["Return flights from UAE","4★ hotel stay","Daily breakfast","Airport transfers","Yerevan city tour"]', '["Explore Yerevan","Lake Sevan — the Pearl of Armenia","Garni Temple & Geghard","Cascade Complex"]', '[{"day":1,"title":"Arrival in Yerevan","detail":"Warm welcome at Zvartnots Airport, private transfer to your 4★ hotel and an evening stroll along Republic Square."},{"day":2,"title":"Yerevan City & Cascade","detail":"Discover the pink-stone capital — the Cascade Complex, Opera House, museums and vibrant cafés."},{"day":3,"title":"Lake Sevan & Highlands","detail":"Day trip to the sparkling Lake Sevan, Sevanavank monastery and the alpine countryside."},{"day":4,"title":"Departure","detail":"Leisurely breakfast, last-minute souvenir shopping and transfer back to the airport."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('discover-istanbul', 'Discover Istanbul', 'tour', 'Türkiye', 'Europe & Asia', 'Istanbul', 'Where two continents and a thousand years meet', 4, 5, 'Twin sharing', 1690, 'AED', 4, 4.8, 1, 1, 1, 'https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=1200&q=80"]', '["Culture","City Break","Popular"]', '["Return flights from UAE","4★ hotel stay","Daily breakfast","Airport transfers","Bosphorus cruise"]', '["Blue Mosque & Hagia Sophia","Grand Bazaar","Bosphorus dinner cruise","Topkapi Palace"]', '[{"day":1,"title":"Arrival in Istanbul","detail":"Private transfer to your hotel in the heart of the old city, evening at leisure."},{"day":2,"title":"Old City Wonders","detail":"Hagia Sophia, the Blue Mosque, Topkapi Palace and the Hippodrome."},{"day":3,"title":"Bazaars & Bosphorus","detail":"The Grand Bazaar, Spice Market and an unforgettable Bosphorus dinner cruise."},{"day":4,"title":"Asian Side & Free Time","detail":"Cross to the Asian shore, explore Kadıköy, then shop or relax at your own pace."},{"day":5,"title":"Departure","detail":"Breakfast and airport transfer with memories to last a lifetime."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('russian-adventure', 'Russian Adventure', 'tour', 'Russia', 'Europe', 'Moscow', 'Imperial grandeur, golden domes & endless boulevards', 4, 5, 'Twin sharing', 2350, 'AED', 4, 4.9, 1, 1, 2, 'https://images.unsplash.com/photo-1513326738677-b964603b136d?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1513326738677-b964603b136d?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1547448415-e9f5b28e570d?auto=format&fit=crop&w=1200&q=80"]', '["Culture","City Break"]', '["Return flights from UAE","4★ hotel stay","Daily breakfast","Airport transfers","Kremlin & Red Square tour"]', '["Red Square & St Basil’s","The Kremlin","Moscow Metro tour","Bolshoi district"]', '[{"day":1,"title":"Arrival in Moscow","detail":"Meet & greet, transfer to your central hotel, evening walk to illuminated Red Square."},{"day":2,"title":"Kremlin & Red Square","detail":"Guided tour of the Kremlin, Cathedral Square and iconic St Basil’s Cathedral."},{"day":3,"title":"Metro & Museums","detail":"The palatial Moscow Metro, Tretyakov Gallery and Arbat Street."},{"day":4,"title":"Day at Leisure","detail":"Optional day trip or free time for shopping and cafés."},{"day":5,"title":"Departure","detail":"Breakfast and transfer to the airport."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('maldives-getaway', 'Maldives Getaway', 'tour', 'Maldives', 'Indian Ocean', 'Malé', 'Turquoise lagoons and your own slice of paradise', 4, 5, 'Twin sharing', 4200, 'AED', 5, 5, 1, 1, 3, 'https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1573843981267-be1999ff37cd?auto=format&fit=crop&w=1200&q=80"]', '["Beach","Honeymoon","Luxury"]', '["Return flights from UAE","5★ resort stay","Half board","Speedboat transfers","Sunset cruise"]', '["Overwater villa","Snorkelling & reefs","Sunset dolphin cruise","Spa & wellness"]', '[{"day":1,"title":"Arrival in Malé","detail":"Speedboat transfer to your resort, welcome drinks and villa check-in."},{"day":2,"title":"Reef & Lagoon","detail":"Snorkelling over vibrant coral reefs and a lazy afternoon by the lagoon."},{"day":3,"title":"Island Hopping","detail":"Visit a local island and enjoy a sunset dolphin cruise."},{"day":4,"title":"Spa & Relax","detail":"Wellness day — spa treatments, watersports and beachfront dining."},{"day":5,"title":"Departure","detail":"Final breakfast and speedboat transfer back to Malé."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('georgia-highlights', 'Georgia Highlights', 'tour', 'Georgia', 'Caucasus', 'Tbilisi', 'Cobbled old towns, wine valleys and dramatic peaks', 4, 5, 'Triple sharing', 1550, 'AED', 4, 4.8, 0, 1, 4, 'https://images.unsplash.com/photo-1565008576549-57569a49371d?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1565008576549-57569a49371d?auto=format&fit=crop&w=1200&q=80"]', '["Culture","Nature","Wine"]', '["Return flights from UAE","4★ hotel stay","Daily breakfast","Airport transfers","Kazbegi day trip"]', '["Old Tbilisi","Kazbegi & Gergeti","Wine tasting in Kakheti","Sulphur baths"]', '[{"day":1,"title":"Arrival in Tbilisi","detail":"Transfer to hotel and an evening walk through the atmospheric old town."},{"day":2,"title":"Tbilisi City Tour","detail":"Narikala Fortress, sulphur baths and the charming backstreets."},{"day":3,"title":"Kazbegi Mountains","detail":"Journey along the Military Highway to the breathtaking Gergeti Trinity Church."},{"day":4,"title":"Kakheti Wine Region","detail":"Tastings in Georgia’s legendary wine country."},{"day":5,"title":"Departure","detail":"Breakfast and airport transfer."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('baku-azerbaijan', 'Baku Escape', 'tour', 'Azerbaijan', 'Caucasus', 'Baku', 'Flame towers, Caspian breezes and old-world charm', 3, 4, 'Twin sharing', 1450, 'AED', 4, 4.7, 0, 1, 5, 'https://images.unsplash.com/photo-1601921004897-c1e6d1f9a4d4?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1601921004897-c1e6d1f9a4d4?auto=format&fit=crop&w=1200&q=80"]', '["City Break","Culture"]', '["Return flights from UAE","4★ hotel stay","Daily breakfast","Airport transfers","Old City tour"]', '["Flame Towers","Icherisheher Old City","Highland Park views","Caspian promenade"]', '[{"day":1,"title":"Arrival in Baku","detail":"Transfer to hotel and a stroll along the Caspian boulevard."},{"day":2,"title":"Old & New Baku","detail":"Icherisheher old city, Maiden Tower and the futuristic Flame Towers."},{"day":3,"title":"Absheron & Gobustan","detail":"Ancient petroglyphs, mud volcanoes and burning mountain."},{"day":4,"title":"Departure","detail":"Breakfast and airport transfer."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('dubai-city-experience', 'Dubai City Experience', 'tour', 'United Arab Emirates', 'Middle East', 'Dubai', 'Sky-high glamour, golden dunes and modern marvels', 3, 4, 'Twin sharing', 1890, 'AED', 5, 4.9, 0, 1, 6, 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1518684079-3c830dcef090?auto=format&fit=crop&w=1200&q=80"]', '["City Break","Family","Luxury"]', '["5★ hotel stay","Daily breakfast","Desert safari","Burj Khalifa tickets"]', '["Burj Khalifa At The Top","Desert safari & BBQ","Dhow dinner cruise","Dubai Mall & Fountain"]', '[{"day":1,"title":"Arrival in Dubai","detail":"Transfer to your 5★ hotel and evening at the Dubai Fountain."},{"day":2,"title":"Modern Dubai","detail":"Burj Khalifa At The Top, Dubai Mall and the Marina."},{"day":3,"title":"Desert Safari","detail":"Dune bashing, camel rides and a starlit BBQ dinner with live shows."},{"day":4,"title":"Departure","detail":"Breakfast and airport transfer."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('umrah-package', 'Umrah Journey', 'umrah', 'Saudi Arabia', 'Middle East', 'Makkah & Madinah', 'A spiritually enriching journey, faultlessly organised', 7, 8, 'Quad sharing', 3200, 'AED', 4, 5, 0, 1, 7, 'https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&w=1200&q=80', '["https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&w=1200&q=80"]', '["Spiritual","Umrah"]', '["Return flights from UAE","Umrah visa","4★ hotels near Haram","Ziyarat tours","Inter-city transfers"]', '["Hotels steps from the Haram","Guided Ziyarat in both cities","Group & family options","Complete visa handling"]', '[{"day":1,"title":"Arrival in Madinah","detail":"Transfer to your hotel near Masjid an-Nabawi."},{"day":2,"title":"Madinah Ziyarat","detail":"Guided visits to the holy sites of Madinah."},{"day":3,"title":"Travel to Makkah","detail":"Comfortable transfer and performing of Umrah."},{"day":4,"title":"Worship & Reflection","detail":"Days of worship at Masjid al-Haram at your own pace."},{"day":8,"title":"Departure","detail":"Final prayers and transfer to the airport."}]', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
