INSERT INTO `Visa` (`country`, `flag`, `type`, `processing`, `note`, `price`, `about`, `documentsRequired`, `documentsProvided`, `published`, `order`, `createdAt`, `updatedAt`) VALUES
  ('United States', '🇺🇸', 'B1/B2 Tourist & Business', '3–6 weeks', 'Full appointment scheduling & DS-160 support', 'AED 1,200', 'Our USA B1/B2 Visit Visa assistance makes a notoriously complex process simple. We prepare and review your DS-160, help you schedule your consular interview, and coach you on what to expect — so you walk in confident. Whether it''s tourism, family visits or business, our team maximises your chances of approval.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","Company NOC Letter","3 Months Bank Statement","DS-160 Confirmation Details"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Insurance","DS-160 Form Preparation","Interview Coaching"]', 1, 0, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('United Kingdom', '🇬🇧', 'Standard Visitor', '3–4 weeks', 'Document checklist & application review', 'AED 950', 'The UK Standard Visitor Visa lets you explore Britain for tourism, family visits or business. We build a tailored document checklist, review every file for consistency, and complete your online application end-to-end — helping you present a strong, credible case to UKVI.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","Company NOC Letter","3 Months Bank Statement","Proof of Accommodation"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Insurance","Online Application Submission","Appointment Booking"]', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Schengen', '🇪🇺', 'Short-stay (Type C)', '2–3 weeks', 'Covers 27 European countries', 'AED 850', 'One Schengen visa, twenty-seven European countries. Our Type C short-stay assistance covers everything from choosing the correct consulate to preparing your travel itinerary and insurance. We make sure your application is complete and compliant so you can focus on planning the trip of a lifetime.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","Company NOC Letter","3 Months Bank Statement","Confirmed Travel Itinerary"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Insurance","Consulate Appointment Booking","Itinerary Preparation"]', 1, 2, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Canada', '🇨🇦', 'Visitor Visa (TRV)', '4–8 weeks', 'Biometrics guidance included', 'AED 1,100', 'Canada''s Temporary Resident Visa (TRV) opens the door to breathtaking landscapes and vibrant cities. We guide you through the online IRCC application, prepare a persuasive cover letter, and walk you through the biometrics step — giving your visitor visa the best possible chance.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","Company NOC Letter","3 Months Bank Statement","Proof of Funds","Purpose of Travel Letter"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Insurance","IRCC Online Submission","Biometrics Guidance"]', 1, 3, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Australia', '🇦🇺', 'Visitor (Subclass 600)', '2–4 weeks', 'Online lodgement handled for you', 'AED 1,050', 'The Australian Visitor Visa (Subclass 600) is your gateway to reefs, rainforests and iconic cities. We handle the full ImmiAccount lodgement, assemble your supporting documents, and manage any additional requests from the department — a genuinely hands-off experience for you.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","Company NOC Letter","3 Months Bank Statement","Proof of Funds"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Insurance","ImmiAccount Lodgement","Document Compilation"]', 1, 4, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('New Zealand', '🇳🇿', 'Visitor Visa', '3–5 weeks', 'End-to-end application support', 'AED 1,000', 'Discover New Zealand''s stunning fjords, mountains and Māori culture with a Visitor Visa. From your very first consultation to final decision, we prepare your application, verify each document, and keep you updated at every stage — end-to-end support with zero guesswork.', '["Passport Copy (valid 6+ months)","UAE Visa / Residence Copy","Emirates ID Copy","Recent Photo (white background)","Company NOC Letter","3 Months Bank Statement","Proof of Onward Travel"]', '["Professional Assistance","Cover Letter","Application Form Filling","Flight & Hotel Reservations","Travel Insurance","Online Application Submission","Status Tracking"]', 1, 5, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO `Testimonial` (`name`, `trip`, `rating`, `quote`, `published`, `order`, `createdAt`, `updatedAt`) VALUES
  ('Ali R.', 'Escape to Armenia', 5, 'My Armenia trip was seamless. Hotels, transfers, and sightseeing were perfectly organised. Highly recommend RadiantWay Travel!', 1, 0, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Fatima S.', 'Discover Istanbul', 5, 'Booking the Turkey package was effortless. Everything from flights to hotel transfers was handled professionally. Istanbul sightseeing was amazing!', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Omar K.', 'Russian Adventure', 5, 'The Russia package exceeded my expectations. Day trips around Moscow were well organised, and the hotel stay was very comfortable. Truly stress-free travel!', 1, 2, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Sara M.', 'Maldives Getaway', 5, 'An absolute dream. From the speedboat transfer to the overwater villa, every detail was taken care of. We just relaxed and enjoyed our honeymoon.', 1, 3, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Bilal A.', 'Umrah Journey', 5, 'A spiritually beautiful and perfectly organised Umrah. Hotels were minutes from the Haram and the team supported us every single step of the way.', 1, 4, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO `Faq` (`question`, `answer`, `published`, `order`, `createdAt`, `updatedAt`) VALUES
  ('Do you arrange the flights?', 'Yes, all our packages include return flights from major UAE airports, ensuring a seamless travel experience from start to finish.', 1, 0, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Are the hotels central/close to attractions?', 'Yes, we carefully select hotels that are centrally located and close to major attractions, offering both comfort and convenience.', 1, 1, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Do you help with visa applications?', 'Yes, we provide full support for visa applications, including USA, UK, Schengen, Canada, Australia, and New Zealand. Our team guides you through the entire process.', 1, 2, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Can I book for solo travellers or families?', 'Yes, our packages are flexible and can be tailored for solo travelers, families, or groups, ensuring everyone enjoys a smooth and memorable journey.', 1, 3, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('Do you offer installment payment options?', 'Yes, we offer easy installment plans. You can secure your booking with a small deposit and pay the remaining amount through flexible installments before departure.', 1, 4, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
